"358 :     public static boolean testNode(
359 :         NodePointer pointer,
360 :         Object node,
361 :         NodeTest test)
362 :     {
363 :         if (test == null) {
364 :             return true;
365 :         }
366 :         if (test instanceof NodeNameTest) {
367 :             if (!(node instanceof Element)) {
368 :                 return false;
369 :             }
370 : 
371 :             NodeNameTest nodeNameTest = (NodeNameTest) test;
372 :             QName testName = nodeNameTest.getNodeName();
373 :             String namespaceURI = nodeNameTest.getNamespaceURI();
374 :             boolean wildcard = nodeNameTest.isWildcard();
375 :             String testPrefix = testName.getPrefix();
376 :             if (wildcard && testPrefix == null) {
377 :                 return true;
378 :             }
379 :             if (wildcard
380 :                 || testName.getName()
381 :                         .equals(JDOMNodePointer.getLocalName(node))) {
382 :                 String nodeNS = JDOMNodePointer.getNamespaceURI(node);
383 :                 return equalStrings(namespaceURI, nodeNS) || nodeNS == null
384 :                         && equalStrings(testPrefix, getPrefix(node));
385 :             }
386 :             return false;
387 :         }
388 :         if (test instanceof NodeTypeTest) {
389 :             switch (((NodeTypeTest) test).getNodeType()) {
390 :                 case Compiler.NODE_TYPE_NODE :
391 :                     return (node instanceof Element) || (node instanceof Document);
392 :                 case Compiler.NODE_TYPE_TEXT :
393 :                     return (node instanceof Text) || (node instanceof CDATA);
394 :                 case Compiler.NODE_TYPE_COMMENT :
395 :                     return node instanceof Comment;
396 :                 case Compiler.NODE_TYPE_PI :
397 :                     return node instanceof ProcessingInstruction;
398 :             }
399 :             return false;
400 :         }
401 :         if (test instanceof ProcessingInstructionTest && node instanceof ProcessingInstruction) {
402 :             String testPI = ((ProcessingInstructionTest) test).getTarget();
403 :             String nodePI = ((ProcessingInstruction) node).getTarget();
404 :             return testPI.equals(nodePI);
405 :         }
406 :         return false;
407 :     }"

